                        axiom_scal_3: "8. Distributivitate (Scalar): (c + d)\\mathbf{u} = c\\mathbf{u} + d\\mathbf{u}",
                        axiom_scal_4: "9. Asociativitate: c(d\\mathbf{u}) = (cd)\\mathbf{u}",
